with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , FLOATER_OR_NOT as FLOATER_INDICATOR
        , cast(null as varchar) as CONTRIBUTORY_INDICATOR
        , cast(null as varchar) as EMPLOYER_CONTRIBUTION_PERCENTAGE
        , cast(null as varchar) as GROUP_SIZE
        , cast(null as varchar) as GROUP_TYPE
        , cast(null as varchar) as MEMBER_COUNT
        , cast(null as varchar) as MASTER_POLICY_NUMBER
        , 'BJAZ_CARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_card_dtls') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as FLOATER_INDICATOR
        , COMP_CONTR as CONTRIBUTORY_INDICATOR
        , COMP_CNTRPER as EMPLOYER_CONTRIBUTION_PERCENTAGE
        , cast(null as varchar) as GROUP_SIZE
        , cast(null as varchar) as GROUP_TYPE
        , cast(null as varchar) as MEMBER_COUNT
        , cast(null as varchar) as MASTER_POLICY_NUMBER
        , 'BJAZ_ECARD_POL_DTLS_CONFIG' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ecard_pol_dtls_config') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as FLOATER_INDICATOR
        , cast(null as varchar) as CONTRIBUTORY_INDICATOR
        , cast(null as varchar) as EMPLOYER_CONTRIBUTION_PERCENTAGE
        , MEMBER_EMP_HEADER as GROUP_SIZE
        , EMPR_EMP_RELATION as GROUP_TYPE
        , TOTAL_NO_PROPOSED as MEMBER_COUNT
        , cast(null as varchar) as MASTER_POLICY_NUMBER
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as FLOATER_INDICATOR
        , cast(null as varchar) as CONTRIBUTORY_INDICATOR
        , cast(null as varchar) as EMPLOYER_CONTRIBUTION_PERCENTAGE
        , cast(null as varchar) as GROUP_SIZE
        , cast(null as varchar) as GROUP_TYPE
        , cast(null as varchar) as MEMBER_COUNT
        , CTNY_MASTER_CONTRACT_ID as MASTER_POLICY_NUMBER
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as FLOATER_INDICATOR
        , cast(null as varchar) as CONTRIBUTORY_INDICATOR
        , cast(null as varchar) as EMPLOYER_CONTRIBUTION_PERCENTAGE
        , cast(null as varchar) as GROUP_SIZE
        , cast(null as varchar) as GROUP_TYPE
        , TOTAL_MEMBER_COUNT as MEMBER_COUNT
        , cast(null as varchar) as MASTER_POLICY_NUMBER
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FLOATER_INDICATOR end) as FLOATER_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONTRIBUTORY_INDICATOR end) as CONTRIBUTORY_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EMPLOYER_CONTRIBUTION_PERCENTAGE end) as EMPLOYER_CONTRIBUTION_PERCENTAGE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROUP_SIZE end) as GROUP_SIZE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROUP_TYPE end) as GROUP_TYPE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_COUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_COUNT end)) as MEMBER_COUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MASTER_POLICY_NUMBER end) as MASTER_POLICY_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when FLOATER_INDICATOR is not null or CONTRIBUTORY_INDICATOR is not null or EMPLOYER_CONTRIBUTION_PERCENTAGE is not null or GROUP_SIZE is not null or GROUP_TYPE is not null or MEMBER_COUNT is not null or MASTER_POLICY_NUMBER is not null
                     then md5(upper(coalesce(cast(FLOATER_INDICATOR as varchar), '') || '|' || coalesce(cast(CONTRIBUTORY_INDICATOR as varchar), '') || '|' || coalesce(cast(EMPLOYER_CONTRIBUTION_PERCENTAGE as varchar), '') || '|' || coalesce(cast(GROUP_SIZE as varchar), '') || '|' || coalesce(cast(GROUP_TYPE as varchar), '') || '|' || coalesce(cast(MEMBER_COUNT as varchar), '') || '|' || coalesce(cast(MASTER_POLICY_NUMBER as varchar), '')))
                end as SAT_POLICY_GROUP_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_GROUP_HASHDIFF is not null
